    let new_count = count.wrapping_add(1 as size_t);
    let new_entries = realloc(
        entries as *mut c_void,
        (::core::mem::size_of::<hashentry_t>() as size_t).wrapping_mul(new_count),
    ) as *mut hashentry_t;
    (*cell).e = new_entries;

    let new_entry = new_entries.add(count as usize);
    (*new_entry).k = strclone(key);
    (*new_entry).v = value;
    (*cell).c = new_count;
}
